int n_queens(int board[], int col, int n)
{
    int count = 0;

    if (col >= n)
        return 1;
    for (int i = 0; i < n; i++) {
        if (queen_safe(board, i, col, n)) {
            board[col] = i;
            count += n_queens(board, col + 1, n);
            board[col] = -1;
        }
    }
    return count;
}

