int verif(int chess[], int l, int col, int n)
{
    int i;
    int j;

    for (i = 0; i < col; i++) {
        if (chess[l * n + i] == 1)
            return 0;
    }
    j = col;
    for (i = l; i >= 0 && j >= 0; i--) {
        if (chess[i * n + j] == 1)
            return 0;
        j--;
    }
    j = col;
    for (i = l; j >= 0 && i < n; i++) {
